// Guards the WRAPPER mark on method expressions (convSelectorExpr). Go's compiler emits an
// autogenerated wrapper for two method-expression shapes, and names it after the expression:
// `I.M` on an interface, and `(*T).M` for a VALUE-receiver method taken off the pointer type. The
// converter renders both as lambdas, and the lambda carries [GoWrapper("<name>")] so the runtime names
// its frame and its reflect PC the way Go does (runtime's TestCallersFromWrapper). The CONTROLS are the
// method-group forms, which ARE the method in Go too and must stay unmarked.

package main

import (
	"go/build"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

func convertMethodExpressionWrapperFixture(t *testing.T) string {
	t.Helper()

	root := t.TempDir()
	appDir := filepath.Join(root, "app")

	writeModuleFile(t, filepath.Join(appDir, "go.mod"), "module example.com/mexpr\n\ngo 1.23\n")
	writeModuleFile(t, filepath.Join(appDir, "main.go"), `package main

import "fmt"

type I interface{ M(x int) int }

type S struct{ v int }

func (s S) value(x int) int { return s.v + x }

func (s *S) pointer(x int) int { return s.v * x }

func main() {
	// POSITIVE 1: an interface method expression.
	ifaceExpr := I.M

	// POSITIVE 2: a value-receiver method taken off the pointer type.
	ptrOfValueExpr := (*S).value

	// CONTROL 1: a value-receiver method off the value type is the method itself.
	valueExpr := S.value

	// CONTROL 2: a pointer-receiver method off the pointer type is the method itself.
	ptrExpr := (*S).pointer

	s := &S{v: 2}
	fmt.Println(ifaceExpr != nil, ptrOfValueExpr(s, 1), valueExpr(*s, 1), ptrExpr(s, 3))
}
`)

	goRoot := build.Default.GOROOT

	if goRoot == "" {
		goRoot = runtime.GOROOT()
	}

	options := Options{
		goRoot:              goRoot,
		goPath:              build.Default.GOPATH,
		go2csPath:           filepath.Join(root, "out"),
		recurse:             true,
		targetPlatform:      runtime.GOOS + "/" + runtime.GOARCH,
		indentSpaces:        4,
		preferVarDecl:       true,
		useChannelOperators: true,
	}

	build.Default.GOROOT = options.goRoot
	build.Default.GOPATH = options.goPath

	if err := NewModuleConverter(options).ConvertModule(appDir); err != nil {
		t.Fatalf("ConvertModule: %v", err)
	}

	return readGenerated(t, filepath.Join(options.go2csPath, "src", "example.com", "mexpr", "main.cs"))
}

func TestMethodExpressionWrapperMark(t *testing.T) {
	mainCs := strings.ReplaceAll(convertMethodExpressionWrapperFixture(t), "\r\n", "\n")

	arms := []struct {
		local string
		want  string // "" for a control: no mark at all
	}{
		{"ifaceExpr", `[GoWrapper("I.M")] (p0, p1) => p0.M(p1)`},
		{"ptrOfValueExpr", `[GoWrapper("(*S).value")] (p0, p1) => value(p0.Value, p1)`},
		{"valueExpr", ""},
		{"ptrExpr", ""},
	}

	for _, arm := range arms {
		line := emittedLineFor(t, mainCs, arm.local)

		if arm.want == "" {
			if strings.Contains(line, "GoWrapper") {
				t.Errorf("%s: the method-group form is the method itself and must stay unmarked: %s", arm.local, line)
			}

			continue
		}

		if !strings.Contains(line, arm.want) {
			t.Errorf("%s: want %s in %s", arm.local, arm.want, line)
		}
	}
}
